#!/usr/bin/env python3
"""Generate the incident timeline, the national research matrix and the
per-institution public-records summaries from data/historical-incidents.csv,
the inventory and the evidence register.

    python3 scripts/build_reports.py

Reads and writes local files only.
"""

import repo_data as rd

NOTE = ("Generated by `scripts/build_reports.py` from "
        "`data/historical-incidents.csv` and `data/website-inventory.csv`. "
        "Do not edit by hand.")
CAVEAT = ("A historical incident does not show that a weakness exists today. "
          "Each entry states whether its sources were opened in full or read "
          "only as search-result excerpts; none has been saved yet, and each "
          "must be saved before it is cited.")


def cell(text):
    return (text or "–").replace("|", "/")


def sources(row):
    links = [f"[source]({row['source_url']})"] if row["source_url"] else []
    if row["supporting_source_url"]:
        links.append(f"[supporting source]({row['supporting_source_url']})")
    extra = [u.strip() for u in row["additional_source_urls"].split(";") if u.strip()]
    links += [f"[further source {n}]({u})" for n, u in enumerate(extra, start=1)]
    return ", ".join(links) if links else "None"


def detail(row, out):
    out.append(f"### {row['incident_id']} — {row['institution']}")
    out.append("")
    out.append(f"- **Label:** {row['label']}")
    out.append(f"- **Confidence:** {row['confidence']}")
    out.append(f"- **Incident date:** {row['incident_date'] or 'Not applicable'}")
    out.append(f"- **Publication date:** {row['publication_date']}")
    out.append(f"- **System concerned:** {row['system_affected'].capitalize()}")
    out.append(f"- **What was reported:** {row['summary']}")
    out.append(f"- **Confirmed by an official body:** {row['confirmed_details'] or 'Nothing.'}")
    out.append(f"- **Reported allegations and unconfirmed details:** {row['alleged_or_unconfirmed_details'] or 'Nothing recorded.'}")
    out.append(f"- **Official investigation announced:** {row['investigation_announced']}")
    out.append(f"- **Investigation outcome:** {row['investigation_outcome'].capitalize()}")
    out.append(f"- **Remediation confirmed:** {row['remediation_confirmed']}")
    out.append(f"- **Source type:** {row['source_type'].capitalize()}")
    out.append(f"- **Sources:** {sources(row)}")
    out.append(f"- **Sources opened in full:** {row['sources_opened'].capitalize()}")
    out.append(f"- **Note:** {row['notes']}")
    out.append("")


def render_timeline():
    _, rows = rd.read_csv(rd.INCIDENTS)
    dated = sorted((r for r in rows if r["incident_date"]),
                   key=lambda r: r["incident_date"], reverse=True)
    undated = [r for r in rows if not r["incident_date"]]
    out = ["# Historical incident timeline", "", NOTE, "", CAVEAT, ""]
    counts = {label: sum(r["label"] == label for r in rows)
              for label in rd.INCIDENT_LABELS}
    out += ["## Summary", "", "| Label | Entries |", "| --- | --- |"]
    out += [f"| {label} | {counts[label]} |" for label in rd.INCIDENT_LABELS]
    out += ["", "## Timeline, most recent first", "",
            "| Date | Institution | System | What was reported | Label | ID |",
            "| --- | --- | --- | --- | --- | --- |"]
    for r in dated:
        out.append(f"| {r['incident_date']} | {cell(r['institution'])} | "
                   f"{r['system_affected'].capitalize()} | {cell(r['summary'])} | "
                   f"{r['label']} | {r['incident_id']} |")
    out += ["", "## Institutions with no incident report found", ""]
    for r in undated:
        out.append(f"- **{r['institution']}** ({r['incident_id']}): {r['summary']} {r['notes']}")
    out += ["", "## Details", ""]
    for r in dated:
        detail(r, out)
    return "\n".join(out)


def render_site(site, incidents):
    own = [r for r in incidents if r["site_id"] == site["site_id"]]
    shared = [r for r in incidents if r["site_id"] == rd.SHARED_SITE_ID]
    confirmed = [r for r in own if r["label"] == "CONFIRMED HISTORICAL INCIDENT"]
    unverified = [r for r in own if r["label"] == "POTENTIAL RISK - NOT VERIFIED"]
    out = [f"# Public-records summary: {site['institution']}", "", NOTE, "",
           "This file summarizes existing publications only. No request was "
           "made to the website, and nothing here is an observation of it.", "",
           "| | |", "| --- | --- |",
           f"| Site ID | {site['site_id']} |",
           f"| Domain | {site['domain']} |",
           f"| Sector | {site['sector']} |",
           f"| Domain verification | {site['domain_verification_status']} "
           f"({site['verification_checks_passed']} of 2 checks) |",
           f"| Verification source | [link]({site['official_source_reference']}) |",
           f"| Verification note | {cell(site['notes'])} |",
           f"| Website assessment | {site['research_status']} |",
           f"| Site report | [{site['domain']}.md]({site['domain']}.md) |"]
    review = rd.REPORTS / f"{site['site_id'].lower()}-public-evidence-review.md"
    if review.exists():
        out.append(f"| Detailed evidence review | [{review.name}]({review.name}) |")
    out += ["", "## Documented incidents and reports", "", CAVEAT, ""]
    out.append(f"{len(confirmed)} confirmed historical incident(s) and "
               f"{len(unverified)} unverified report(s) are recorded for this institution.")
    out.append("")
    if own:
        for r in own:
            detail(r, out)
    out += ["## Shared government infrastructure", "",
            "These incidents affected shared services. No source read "
            "attributes them to this institution specifically.", ""]
    for r in shared:
        out.append(f"- {r['incident_id']} ({r['incident_date']}): {r['summary']}")
    out += ["", "## Publicly observable security posture", "",
            "No browser observation has been made. Every item in the "
            "[assessment checklist](../../research/assessment-checklist.md), "
            "and public DNS and certificate records, are **NOT TESTED** for "
            "this site. Observation starts only after the domain is `VERIFIED`.",
            "", "## Sri Lanka CERT guideline",
            "", "See the [compliance mapping](../../research/cert-compliance-mapping.md). "
            "No requirement has been assessed for this institution.",
            "", "## What remains unverified", ""]
    if site["domain_verification_status"] != "VERIFIED":
        out.append("- Domain verification is not complete.")
    open_cases = [r["incident_id"] for r in own
                  if r["investigation_outcome"] == "UNKNOWN"]
    if open_cases:
        out.append("- The investigation outcome is unknown for: "
                   + ", ".join(open_cases) + ".")
    if own:
        out.append("- Every source above needs to be opened in full and saved, "
                   "and a primary statement located where only news reporting exists.")
    out.append("- The current configuration of the website is unknown.")
    out.append("")
    return "\n".join(out)


def render_matrix():
    _, sites = rd.read_csv(rd.INVENTORY)
    _, incidents = rd.read_csv(rd.INCIDENTS)
    _, findings = rd.read_csv(rd.REGISTER)
    out = ["# National government website research matrix", "", NOTE.replace(
        "`data/website-inventory.csv`",
        "`data/website-inventory.csv` and `evidence/evidence-register.csv`"), "",
        "This matrix shows, for each of the ten institutions, the public "
        "evidence found, what is unknown and where the research stands. It "
        "records past events and open questions. It identifies no current "
        "vulnerability in any website, and no request was made to any of them.",
        "", CAVEAT, "",
        "Labels are defined in [evidence classification](../docs/evidence-classification.md). "
        "Research priorities are in the [confidence and risk matrix](../docs/confidence-risk-matrix.md). "
        "Incident details are in the [historical incident timeline](historical-incident-timeline.md).",
        "", "## Overview", "",
        "| ID | Official domain | Domain verification | Confirmed incidents on record | Unverified reports | Current observed evidence | Research status |",
        "| --- | --- | --- | --- | --- | --- | --- |"]
    blocks = []
    with_site_incident = 0
    for s in sites:
        own = [r for r in incidents if r["site_id"] == s["site_id"]]
        conf = [r for r in own if r["label"] == "CONFIRMED HISTORICAL INCIDENT"]
        unv = [r for r in own if r["label"] == "POTENTIAL RISK - NOT VERIFIED"]
        observed = [f for f in findings if f["website"] == s["domain"]]
        if any(r["system_affected"] == "WEBSITE" for r in conf):
            with_site_incident += 1
        status = ("Public-records discovery done; website observation "
                  + ("not started, waiting for domain verification"
                     if s["domain_verification_status"] != "VERIFIED"
                     else s["research_status"].lower()))
        out.append(f"| {s['site_id']} | {s['domain']} | {s['domain_verification_status']} | "
                   f"{len(conf)} | {len(unv)} | {len(observed)} | {s['research_status']} |")
        b = [f"### {s['site_id']} — {s['institution']}", "",
             f"- **Official domain:** `{s['domain']}`",
             f"- **Official domain verification source:** [{s['domain_verification_status']}, "
             f"{s['verification_checks_passed']} of 2 checks]({s['official_source_reference']}). {s['notes']}.",
             "- **Historical incident evidence:** " + (
                 " ".join(f"{r['incident_id']} ({r['incident_date']}, "
                          f"{r['system_affected'].lower()}): {r['summary']}" for r in conf)
                 if conf else "No confirmed incident on record. "
                 + " ".join(r["summary"] for r in own if r["label"] == "NO PUBLIC EVIDENCE AVAILABLE")),
             "- **Current observed security evidence:** " + (
                 f"{len(observed)} row(s) in the evidence register." if observed
                 else "None. No browser observation has been made."),
             "- **Potential risks:** " + (
                 " ".join(f"{r['incident_id']} (unverified report, {r['system_affected'].lower()}): "
                          f"{r['summary']}" for r in unv)
                 if unv else "None recorded. No current risk is inferred from past incidents."),
             ]
        unknowns = []
        if s["domain_verification_status"] != "VERIFIED":
            unknowns.append("domain verification is incomplete")
        pending = [r["incident_id"] for r in own if r["investigation_outcome"] == "UNKNOWN"]
        if pending:
            unknowns.append("investigation outcome unknown for " + ", ".join(pending))
        unknowns.append("the website's current configuration has not been observed")
        text = "; ".join(unknowns)
        b.append("- **Unknowns:** " + text[0].upper() + text[1:] + ".")
        levels = sorted({r["confidence"] for r in own if r["confidence"] in rd.CONFIDENCES},
                        key=rd.CONFIDENCES.index)
        b.append("- **Confidence:** " + (
            "Incident records: " + ", ".join(levels) + ". " if levels else "No incident record to rate. ")
            + "No observation exists to rate.")
        b.append(f"- **Research status:** {status}. [Public-records summary]"
                 f"(individual-sites/{s['domain']}-public-records.md).")
        b.append("")
        blocks += b
    labels = {label: sum(r["label"] == label for r in incidents)
              for label in rd.INCIDENT_LABELS}
    out += ["", "## Totals", "",
            f"- Institutions selected: {len(sites)}",
            f"- Institutions with a confirmed incident affecting their website: {with_site_incident}",
            f"- Domains fully verified: {sum(s['domain_verification_status'] == 'VERIFIED' for s in sites)}",
            f"- Websites observed: {len({f['website'] for f in findings})}",
            f"- Incident records: {len(incidents)} "
            f"({labels['CONFIRMED HISTORICAL INCIDENT']} confirmed, "
            f"{labels['POTENTIAL RISK - NOT VERIFIED']} unverified, "
            f"{labels['NO PUBLIC EVIDENCE AVAILABLE']} with no evidence of a cyber incident)",
            "- Confirmed current security weaknesses: 0",
            "", "## By institution", ""]
    out += blocks
    shared = [r for r in incidents if r["site_id"] == rd.SHARED_SITE_ID]
    out += ["## Shared infrastructure", "",
            "No source read attributes these to a specific institution.", ""]
    out += [f"- {r['incident_id']} ({r['incident_date']}): {r['summary']}" for r in shared]
    out += ["", "## What this matrix does not support", "",
            "- Any statement that a listed website is vulnerable today.",
            "- Any statement that an institution does not comply with Sri Lanka CERT's guidelines.",
            "- Any link between these incidents and AI-generated code.",
            "- Any ranking of institutions by security.", ""]
    return "\n".join(out)


def outputs():
    _, sites = rd.read_csv(rd.INVENTORY)
    _, incidents = rd.read_csv(rd.INCIDENTS)
    files = {rd.TIMELINE: render_timeline(), rd.MATRIX: render_matrix()}
    for site in sites:
        files[rd.public_records_path(site["domain"])] = render_site(site, incidents)
    return files


if __name__ == "__main__":
    for path, text in outputs().items():
        path.write_text(text, encoding="utf-8")
        print(f"Wrote {path.relative_to(rd.ROOT)}")
